import Foundation
import LKSync

/// Onboarding starter deck (C17), same as web: at the end of setup every pack adds the words of the first 3 topics of its exam
/// (web/js/onboard.js `topicsFor(ex).slice(0, 3)` → `D.addWord` = `Core.Cards.add`), skipping words already in the deck.
/// The word entries are the bundled pack `starter.json` (generated by scripts/native/starter.mjs from the web data, never typed here);
/// the expected result is vectors/starter-deck.json, produced by running the real web `Cards.make`.
public enum StarterDeck {
    public struct Pack: Sendable {
        public let byExam: [String: [String]]
        public let topics: [String: [JSON]]
        public init(json: JSON) {
            byExam = (json["byExam"]?.object ?? [:]).mapValues { ($0.array ?? []).compactMap(\.string) }
            topics = (json["topics"]?.object ?? [:]).mapValues { $0.array ?? [] }
        }
    }

    /// The bundled pack (LKStore resource). Nil only if the resource is missing (a packaging bug the tests catch).
    public static func bundled() -> Pack? {
        guard let url = Bundle.module.url(forResource: "starter", withExtension: "json"), let data = try? Data(contentsOf: url), let json = try? JSON.parse(data) else { return nil }
        return Pack(json: json)
    }

    /// Web `examOf(TR[track], variant)`: IELTS General Training is `ieltsgt`, TOEIC/TOEFL map 1:1, Communication + Workplace are `general`; no pick = web default `ielts`.
    public static func exam(track: String?, variant: String = "") -> String {
        switch track {
        case "ielts", nil: return variant == "gt" ? "ieltsgt" : "ielts"
        case "toeic": return "toeic"
        case "toefl": return "toefl"
        default: return "general"
        }
    }

    static func s(_ v: JSON?, _ d: String = "") -> JSON { JSON.truthy(v) ? v! : .string(d) }

    /// `Core.Cards.make(entry)` (web/js/core.js), clock injected.
    public static func make(_ e: JSON, now: Double) -> JSON {
        var o: [String: JSON] = [:]
        o["word"] = e["word"] ?? .null
        for k in ["ipa", "ipaUS", "pos", "vi", "def", "ex"] { o[k] = s(e[k]) }
        o["col"] = JSON.truthy(e["col"]) ? e["col"]! : .array([])
        o["syn"] = JSON.truthy(e["syn"]) ? e["syn"]! : .array([])
        o["level"] = s(e["level"]); o["topic"] = s(e["topic"], "mine"); o["emoji"] = s(e["emoji"], "📘"); o["image"] = s(e["image"])
        o["imageCredit"] = JSON.truthy(e["imageCredit"]) ? e["imageCredit"]! : .null
        o["audio"] = s(e["audio"])
        o["sentences"] = .array(Array((e["sentences"]?.array ?? []).prefix(2)))
        o["contexts"] = .array([]); o["note"] = ""; o["added"] = .number(now); o["srs"] = MigrationImport.newState(now)
        if JSON.truthy(e["tl"]), e["tl"]?.string != "en" { o["tl"] = e["tl"]! }
        return .object(o)
    }

    /// Cards in web insertion order (topic by topic, first occurrence of a word wins), each with `mod = now` like `Cards._add`.
    public static func cards(exam: String, pack: Pack, now: Double) -> [(key: String, card: JSON)] {
        var seen = Set<String>(), out: [(String, JSON)] = []
        for id in pack.byExam[exam] ?? [] {
            for e in pack.topics[id] ?? [] {
                let key = MigrationImport.tlKey(e["word"], e["tl"])
                if !seen.insert(key).inserted { continue }
                var c = make(e, now: now); c["mod"] = .number(now)
                out.append((key, c))
            }
        }
        return out
    }

    /// Adds the starter deck to [doc]; words already there stay untouched (web `if (!D.inDeck(w.word))`), a tombstone for an added word is cleared.
    public static func add(to doc: inout SyncDoc, exam: String, pack: Pack, now: Double) {
        for (key, card) in cards(exam: exam, pack: pack, now: now) where doc.cards[key] == nil {
            doc.cards[key] = card
            doc.deleted[key] = nil
        }
    }
}
